append.INFRASTRUCTURE_USINGS:
using Azure.Core;
using Azure.Identity;
using Npgsql;

append.INFRASTRUCTURE_REGISTRATIONS:
var connectionString = configuration.GetConnectionString("Postgres");

if (string.IsNullOrWhiteSpace(connectionString))
    throw new InvalidOperationException("Connection string 'Postgres' is required.");

var dataSourceBuilder = new NpgsqlDataSourceBuilder(connectionString);

if (string.IsNullOrEmpty(dataSourceBuilder.ConnectionStringBuilder.Password))
{
    var credential = new DefaultAzureCredential(new DefaultAzureCredentialOptions
    {
        ManagedIdentityClientId = configuration["AZURE_CLIENT_ID"],
    });

    dataSourceBuilder.UsePeriodicPasswordProvider(
        async (_, cancellationToken) =>
        {
            var token = await credential.GetTokenAsync(
                new TokenRequestContext(["https://ossrdbms-aad.database.windows.net/.default"]),
                cancellationToken).ConfigureAwait(false);

            return token.Token;
        },
        TimeSpan.FromMinutes(55),
        TimeSpan.FromSeconds(10));
}

var dataSource = dataSourceBuilder.Build();

services.AddDbContext<ApplicationDbContext>(options => options.UseNpgsql(dataSource));
services.AddSingleton(dataSource);
services.AddScoped<IDapperConnectionFactory, DapperConnectionFactory>();
